package main

import (
	"fmt"
	"log"
	"net"
	"net/dns"
	"sync"
)

var (
	ips = map[string][]string{}
	mu  sync.Mutex
)

func main() {
	// Create a new DNS server
	dns.HandleFunc(".", func(w dns.ResponseWriter, r *dns.Msg) {
		// Forward the request to 8.8.8.8 and 1.1.1.1
		go func() {
			_, err := net.Dial("udp", "8.8.8.8:53")
			if err != nil {
				log.Println(err)
				return
			}
			_, err = net.Dial("udp", "1.1.1.1:53")
			if err != nil {
				log.Println(err)
				return
			}
			// Forward the request
			go forwardRequest(w, r)
		}()
	})

	// Start the DNS server
	if err := dns.ListenAndServe("udp", ":53", nil); err != nil {
		log.Fatal(err)
	}
}

func forwardRequest(w dns.ResponseWriter, r *dns.Msg) {
	// Create a new UDP connection to 8.8.8.8 and 1.1.1.1
	conn, err := net.Dial("udp", "8.8.8.8:53")
	if err != nil {
		log.Println(err)
		return
	}
	defer conn.Close()

	// Send the request to 8.8.8.8
	_, err = conn.Write(r)
	if err != nil {
		log.Println(err)
		return
	}

	// Read the response from 8.8.8.8
	buf := make([]byte, 1024)
	n, err := conn.Read(buf)
	if err != nil {
		log.Println(err)
		return
	}

	// Parse the response
	m := dns.Msg{}
	m.SetMsg(buf[:n])
	if m.Truncated {
		log.Println("Truncated response")
		return
	}

	// Store the resolved IP in the map
	mu.Lock()
	ips[m.Question[0].Name] = m.Answer
	mu.Unlock()

	// Send the response back to the client
	w.WriteMsg(m)
}



